const cfgRes = $('Odoo: get config').first().json;
if (cfgRes.error || !cfgRes.result) throw new Error('Odoo config not found. Check ODOO_* env vars and sunguard_crm.ids.');
const cfg = JSON.parse(cfgRes.result);
const context = { allowed_company_ids: [cfg.company_id] };

return [{
  json: {
    rpc: {
      model: 'crm.lead',
      method: 'search_read',
      args: [[['company_id', '=', cfg.company_id], ['stage_id', '=', cfg.stage_ids.Won]]],
      kwargs: { fields: ['id', 'name', 'contact_name', 'email_from', 'phone', 'city', 'partner_id', 'tag_ids', 'x_lead_ref'], limit: 20, context }
    }
  }
}];

const cfg = JSON.parse($('Odoo: get config').first().json.result);
const context = { allowed_company_ids: [cfg.company_id] };
const res = $input.first().json;
if (res.error) throw new Error('Odoo Won leads: ' + (res.error.data?.message || res.error.message));
const leads = res.result || [];
if (!leads.length) return [];

const refs = leads.map(l => 'CRM-' + l.id);
return [{
  json: {
    leads,
    rpc: {
      model: 'sale.order',
      method: 'search_read',
      args: [[['company_id', '=', cfg.company_id], ['client_order_ref', 'in', refs]]],
      kwargs: { fields: ['id', 'name', 'client_order_ref'], context }
    }
  }
}];

const cfg = JSON.parse($('Odoo: get config').first().json.result);
const context = { allowed_company_ids: [cfg.company_id] };
const soRes = $input.first().json;
if (soRes.error) throw new Error('Odoo existing SOs: ' + (soRes.error.data?.message || soRes.error.message));
const existingRefs = new Set((soRes.result || []).map(s => s.client_order_ref));
const leads = $('Check existing SOs').first().json.leads.filter(l => !existingRefs.has('CRM-' + l.id));
if (!leads.length) return [];

return [{
  json: {
    leads,
    rpc: {
      model: 'product.product',
      method: 'search_read',
      args: [[['company_id', '=', cfg.company_id]]],
      kwargs: { fields: ['id', 'default_code', 'name', 'list_price'], context }
    }
  }
}];

const cfg = JSON.parse($('Odoo: get config').first().json.result);
const context = { allowed_company_ids: [cfg.company_id] };
const prodRes = $input.first().json;
if (prodRes.error) throw new Error('Odoo products: ' + (prodRes.error.data?.message || prodRes.error.message));

const PRODUCTS_FOR_TAG = {
  'Solar Panel': ['SG-001', 'SG-002'],
  'Inverter': ['SG-004'],
  'Battery': ['SG-003'],
  'Hybrid System': ['SG-001', 'SG-002', 'SG-003', 'SG-004'],
  'CCTV': ['SG-006', 'SG-007', 'SG-008']
};
const tagName = Object.fromEntries(Object.entries(cfg.tag_ids).map(([k, v]) => [v, k]));
const byCode = Object.fromEntries((prodRes.result || []).map(p => [p.default_code, p]));
const leads = $('Fetch SunGuard products').first().json.leads;
const noop = { model: 'res.partner', method: 'search_read', args: [[['id', '=', 0]]], kwargs: { fields: ['id'], limit: 1, context } };

return leads.map(l => {
  const tags = (l.tag_ids || []).map(t => tagName[t]).filter(t => PRODUCTS_FOR_TAG[t]);
  const codes = [...new Set(tags.flatMap(t => PRODUCTS_FOR_TAG[t]))];
  const order_line = codes.map(c => byCode[c]).filter(Boolean).map(p => [0, 0, {
    product_id: p.id,
    product_uom_qty: 1,
    price_unit: p.list_price
  }]);
  const existingPartnerId = Array.isArray(l.partner_id) ? l.partner_id[0] : (l.partner_id || null);
  const email = String(l.email_from || '').trim();
  const domain = existingPartnerId
    ? null
    : (email ? [['email', '=ilike', email], '|', ['company_id', '=', cfg.company_id], ['company_id', '=', false]]
             : [['name', '=ilike', String(l.contact_name || l.name).trim()], '|', ['company_id', '=', cfg.company_id], ['company_id', '=', false]]);
  return {
    json: {
      lead: l,
      existingPartnerId,
      order_line,
      rpc: domain
        ? { model: 'res.partner', method: 'search_read', args: [domain], kwargs: { fields: ['id', 'name'], limit: 1, context } }
        : noop
    }
  };
});

const cfg = JSON.parse($('Odoo: get config').first().json.result);
const context = { allowed_company_ids: [cfg.company_id] };
const src = $('Prepare partner search').all();
const noop = { model: 'res.partner', method: 'search', args: [[['id', '=', 0]]], kwargs: { limit: 1, context } };

return $input.all().map((it, i) => {
  const d = src[i].json;
  const r = it.json || {};
  if (r.error) throw new Error('Odoo partner search: ' + (r.error.data?.message || r.error.message));
  const foundId = d.existingPartnerId || (r.result && r.result[0] ? r.result[0].id : null);
  if (foundId) {
    return { json: { ...d, foundPartnerId: foundId, created: false, rpc: noop } };
  }
  const l = d.lead;
  return {
    json: {
      ...d,
      foundPartnerId: null,
      created: true,
      rpc: {
        model: 'res.partner',
        method: 'create',
        args: [{
          name: String(l.contact_name || l.name || 'Customer').trim(),
          email: l.email_from ? String(l.email_from).trim() : false,
          phone: l.phone ? String(l.phone).trim() : false,
          city: l.city ? String(l.city).trim() : false,
          company_id: cfg.company_id
        }],
        kwargs: { context }
      }
    }
  };
});

const cfg = JSON.parse($('Odoo: get config').first().json.result);
const context = { allowed_company_ids: [cfg.company_id] };
const src = $('Prepare partner create').all();
const noop = { model: 'crm.lead', method: 'search', args: [[['id', '=', 0]]], kwargs: { limit: 1, context } };

return $input.all().map((it, i) => {
  const d = src[i].json;
  const r = it.json || {};
  if (r.error) throw new Error('Odoo partner create: ' + (r.error.data?.message || r.error.message));
  const partnerId = d.created ? r.result : d.foundPartnerId;
  const needsLink = !d.existingPartnerId || d.existingPartnerId !== partnerId;
  return {
    json: {
      ...d,
      partnerId,
      rpc: needsLink
        ? { model: 'crm.lead', method: 'write', args: [[d.lead.id], { partner_id: partnerId }], kwargs: { context } }
        : noop
    }
  };
});

const cfg = JSON.parse($('Odoo: get config').first().json.result);
const context = { allowed_company_ids: [cfg.company_id] };
const src = $('Link partner on lead').all();

return $input.all().map((it, i) => {
  const d = src[i].json;
  const r = it.json || {};
  if (r.error) throw new Error('Odoo link partner: ' + (r.error.data?.message || r.error.message));
  return {
    json: {
      ...d,
      rpc: {
        model: 'sale.order',
        method: 'create',
        args: [{
          partner_id: d.partnerId,
          company_id: cfg.company_id,
          opportunity_id: d.lead.id,
          client_order_ref: 'CRM-' + d.lead.id,
          order_line: d.order_line
        }],
        kwargs: { context }
      }
    }
  };
});

const cfg = JSON.parse($('Odoo: get config').first().json.result);
const context = { allowed_company_ids: [cfg.company_id] };
const src = $('Prepare draft SO').all();

return $input.all().map((it, i) => {
  const d = src[i].json;
  const r = it.json || {};
  if (r.error || !r.result) throw new Error('Odoo create SO: ' + JSON.stringify(r.error || r).slice(0, 200));
  return {
    json: {
      ...d,
      soId: r.result,
      rpc: {
        model: 'sale.order',
        method: 'search_read',
        args: [[['id', '=', r.result]]],
        kwargs: { fields: ['id', 'name'], limit: 1, context }
      }
    }
  };
});

const cfg = JSON.parse($('Odoo: get config').first().json.result);
const context = { allowed_company_ids: [cfg.company_id] };
const src = $('Read SO name').all();

return $input.all().map((it, i) => {
  const d = src[i].json;
  const r = it.json || {};
  if (r.error) throw new Error('Odoo get SO name: ' + (r.error.data?.message || r.error.message));
  const soName = r.result && r.result[0] ? r.result[0].name : ('SO #' + d.soId);
  const customer = String(d.lead.contact_name || d.lead.name || 'Customer').trim();
  const ref = d.lead.x_lead_ref ? String(d.lead.x_lead_ref).trim() : ('Odoo #' + d.lead.id);
  const alert = `🏆 WON ${ref} — Draft SO ${soName} created for ${customer}`;
  return {
    json: {
      alert,
      rpc: {
        model: 'crm.lead',
        method: 'message_post',
        args: [[d.lead.id]],
        kwargs: {
          body: `Draft Sales Order ${soName} created for ${customer} (ref CRM-${d.lead.id}).`,
          message_type: 'comment',
          subtype_xmlid: 'mail.mt_note',
          context
        }
      }
    }
  };
});
